_d256_output_cache = {}
_d256_last_input = None
_d256_last_entry = None


def _compute_d256(entry) -> None:
    (
        initial_solve_launcher,
        middle_solve_launcher,
        update_launcher,
        middle_launcher,
        final_solve_launcher,
        final_update_launcher,
    ) = (
        _d256_launchers_for_current_queue(
            entry[1], entry[3], entry[6], entry[0].shape[0]
        )
    )
    initial_solve_launcher(entry[1], entry[3], entry[6])
    update_launcher(entry[1], entry[3], entry[6])
    middle_solve_launcher(entry[3], entry[6])
    middle_launcher(entry[3], entry[6])
    final_solve_launcher(entry[3], entry[6])
    final_update_launcher(entry[3], entry[6])


def _run_d256(data: torch.Tensor) -> torch.Tensor:
    global _d256_last_input, _d256_last_entry
    if _d256_last_input is data:
        entry = _d256_last_entry
    else:
        key = id(data)
        entry = _d256_output_cache.get(key)
        if entry is None or entry[0] is not data:
            output = torch.zeros_like(
                data, memory_format=torch.contiguous_format
            )
            sidecar = torch.empty(
                data.shape[0] * _D256_SIDECAR_MATRIX_ELEMENTS,
                dtype=torch.float16,
                device=data.device,
            )
            entry = [
                data,
                _as_numba_flat_array(data),
                output,
                _as_numba_flat_array(output),
                output.transpose(-2, -1),
                sidecar,
                _as_numba_half_array(sidecar),
                None,
            ]
            _d256_output_cache[key] = entry
        _d256_last_input = data
        _d256_last_entry = entry
    graph = entry[7]
    if graph is None:
        _compute_d256(entry)
        graph = torch.cuda.CUDAGraph()
        with torch.cuda.graph(graph):
            _compute_d256(entry)
        entry[7] = graph
    graph.replay()
    return entry[4]


